script:
function setupForm({ doc, createToast }) {
  return {
    actions: [
      {
        label: "Open Linked CRM Lead",
        onClick: () => {
          if (doc.lead) {
            window.open(`/crm/leads/${doc.lead}`, "_blank")
          } else {
            createToast({
              title: "No CRM Lead linked to this Deal",
              icon: "info",
            })
          }
        }
      }
    ]
  }
}
